// Initialize state machine
const input = $input.first().json;
const state = {
  run_id: $execution.id,
  correlation_id: input.correlation_id || 'UNKNOWN',
  state: 'RECEIVED',
  previous_state: null,
  reason_code: 'INIT',
  timestamp: new Date().toISOString(),
  workflow_id: $workflow.id,
  execution_id: $execution.id,
  repository: null,
  issue_number: null,
  lock_generation: null,
  builder_ctid: 8001,
  task_id: 'ghiw_source_manifest_v1',
  artifact_sha256: null,
  mutation_approval_id: null
};
return {json: state};

// Input validation with forbidden field detection
const ALLOWED_SCHEMA_VERSION = '1.0';
const ALLOWED_OPERATIONS = ['contract-check', 'process-canary-issue'];
const ALLOWLISTED_REPOS = ['xxammaxx/n8n-blueprint-workflow'];
const SERVER_BUILDER_CTID = 8001;
const SERVER_BUILDER_ID = 'e3r6-canary-001';
const SERVER_TASK_ID = 'ghiw_source_manifest_v1';
const FORBIDDEN_FIELDS = [
  'url', 'repository_url', 'command', 'commands', 'shell', 'script',
  'args', 'argv', 'env', 'environment', 'credential', 'credential_id',
  'token', 'api_key', 'ssh_key', 'ctid', 'builder_ctid', 'builder_id',
  'workspace', 'path', 'working_directory', 'dry_run', 'max_fix_loops',
  'branch', 'commit', 'pull_request'
];
const KNOWN_FIELDS = ['schema_version', 'operation', 'repository', 'issue_number',
                      'correlation_id', 'mutation_approval_id', 'task_id'];
const state = $input.first().json;
const input = state.raw_input || $input.first().json;

for (const field of FORBIDDEN_FIELDS) {
  if (field in input) {
    state.state = 'REJECTED';
    state.reason_code = 'FORBIDDEN_FIELD';
    state.reason_detail = 'Field ' + field + ' is forbidden';
    return {json: state};
  }
}

for (const key of Object.keys(input)) {
  if (!KNOWN_FIELDS.includes(key)) {
    state.state = 'REJECTED';
    state.reason_code = 'UNKNOWN_FIELD';
    state.reason_detail = 'Unknown field: ' + key;
    return {json: state};
  }
}

if (!input.schema_version) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_SCHEMA_VERSION'; return {json: state};
}
if (input.schema_version !== ALLOWED_SCHEMA_VERSION) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_SCHEMA_VERSION'; return {json: state};
}
if (!input.operation) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_OPERATION'; return {json: state};
}
if (!ALLOWED_OPERATIONS.includes(input.operation)) {
  state.state = 'REJECTED'; state.reason_code = 'UNKNOWN_OPERATION'; return {json: state};
}
if (!input.repository) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_REPOSITORY'; return {json: state};
}
if (!ALLOWLISTED_REPOS.includes(input.repository)) {
  state.state = 'REJECTED'; state.reason_code = 'REPOSITORY_NOT_ALLOWLISTED'; return {json: state};
}
if (input.issue_number !== undefined) {
  if (!Number.isInteger(input.issue_number) || input.issue_number < 1) {
    state.state = 'REJECTED'; state.reason_code = 'INVALID_ISSUE_NUMBER'; return {json: state};
  }
}
if (!input.correlation_id) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_CORRELATION_ID'; return {json: state};
}
if (!/^GHIW-E4-[A-Za-z0-9_-]+$/.test(input.correlation_id)) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_CORRELATION_ID'; return {json: state};
}
if (!input.mutation_approval_id) {
  state.state = 'REJECTED'; state.reason_code = 'MISSING_MUTATION_APPROVAL_ID'; return {json: state};
}
if (input.task_id && input.task_id !== SERVER_TASK_ID) {
  state.state = 'REJECTED'; state.reason_code = 'INVALID_TASK_ID'; return {json: state};
}

state.state = 'INPUT_VALIDATED';
state.reason_code = 'VALIDATION_PASSED';
state.builder_ctid = SERVER_BUILDER_CTID;
state.builder_id = SERVER_BUILDER_ID;
state.task_id = SERVER_TASK_ID;
state.repository = input.repository;
state.issue_number = input.issue_number;
state.correlation_id = input.correlation_id;
state.mutation_approval_id = input.mutation_approval_id;
state.raw_input = input;

return {json: state};

// Path decision: contract-check vs process-canary-issue
const state = $input.first().json;
if (state.state !== 'INPUT_VALIDATED') {
  state.state = 'FAILED';
  state.reason_code = 'UNEXPECTED_STATE';
  return {json: state};
}
const operation = state.raw_input?.operation;
if (operation === 'contract-check') {
  state.state = 'CONTRACT_CHECK_COMPLETED';
  state.reason_code = 'CONTRACT_CHECK_PASSED';
  state.contract_check_result = {
    schema_version: '1.0',
    operation: 'contract-check',
    allowed_operations: ['contract-check', 'process-canary-issue'],
    builder_ctid: state.builder_ctid,
    builder_id: state.builder_id,
    task_id: state.task_id,
    allowlisted_repos: ['xxammaxx/n8n-blueprint-workflow'],
    canary_execution_authorized: false,
    contract_valid: true,
    checked_at: new Date().toISOString()
  };
} else if (operation === 'process-canary-issue') {
  state.state = 'INPUT_VALIDATED';
  state.reason_code = 'READY_FOR_CANARY_E4_R3';
  state.canary_authorized = false;
} else {
  state.state = 'REJECTED';
  state.reason_code = 'UNKNOWN_OPERATION';
}
return {json: state};
